begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
insert into auth.users(id,aud,role,email,created_at,updated_at) values('16500000-0000-4000-8000-000000000010','authenticated','authenticated','sessions-manager@example.test',now(),now());
insert into public.profiles(id,role,full_name,is_active) values('16500000-0000-4000-8000-000000000010','academic_manager','TEST-SESSIONS',true);
insert into public.b2c_classes(id,program_slug,name,capacity) values('16500000-0000-4000-8000-000000000001','tieng-anh','TEST-SESSIONS',10);
insert into public.b2c_students(id,source_key,full_name) values('16500000-0000-4000-8000-000000000020','test-sessions','TEST-SESSIONS');
insert into public.b2c_enrollments(id,source_key,class_id,student_id,registered_sessions) values('16500000-0000-4000-8000-000000000030','test-sessions','16500000-0000-4000-8000-000000000001','16500000-0000-4000-8000-000000000020',8);
insert into public.b2c_class_meetings(id,request_id,class_id,starts_at,ends_at,status,created_by,updated_by)
 select ('16500000-0000-4000-8000-'||lpad((n+100)::text,12,'0'))::uuid,gen_random_uuid(),'16500000-0000-4000-8000-000000000001',now()+n*interval '1 day',now()+n*interval '1 day'+interval '1 hour',case when n=-2 then 'cancelled' else 'planned' end,'16500000-0000-4000-8000-000000000010','16500000-0000-4000-8000-000000000010'
 from unnest(array[-9,-8,-7,-6,-5,-2,2]) n;
insert into public.b2c_student_attendance(meeting_id,enrollment_id,status,updated_by)
 select id,'16500000-0000-4000-8000-000000000030',case when starts_at<now()-interval '8 days' then 'present' when starts_at<now()-interval '7 days' then 'late' when starts_at<now()-interval '6 days' then 'makeup' when starts_at<now()-interval '5 days' then 'absent' when starts_at<now()-interval '4 days' then 'excused' else 'present' end,'16500000-0000-4000-8000-000000000010' from public.b2c_class_meetings where class_id='16500000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"16500000-0000-4000-8000-000000000010","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.summary',(public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->'session_summary')::text,true);
select is(current_setting('test.summary')::jsonb->>'attended','3','Only present/late/makeup in past noncancelled meetings count');
select is(current_setting('test.summary')::jsonb->>'absent','1','Unexcused absences separate');
select is(current_setting('test.summary')::jsonb->>'excused','1','Excused absences separate');
select is(current_setting('test.summary')::jsonb->>'makeup','1','Makeup included once in attended');
select is(current_setting('test.summary')::jsonb->>'remaining','5','Remaining uses registration minus attended');
select is(public.read_teacher_b2c_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->'session_summary',current_setting('test.summary')::jsonb,'Shared teacher reader returns matching totals for manager');
reset role;
update public.b2c_enrollments set registered_sessions=null where id='16500000-0000-4000-8000-000000000030';
set local role authenticated;
select ok((public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->'session_summary'->>'remaining') is null,'Unknown registration remains unknown');
reset role;
update public.b2c_enrollments set registered_sessions=2 where id='16500000-0000-4000-8000-000000000030';
set local role authenticated;
select is(public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->'session_summary'->>'remaining','-1','Overrun retained rather than hidden');
select is(public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students',0,'no match')->'rows','[]'::jsonb,'Search still filters rows');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students')$$,'42501',null,'Unauthorized actor denied');
reset role;
insert into auth.users(id) values('16500000-0000-4000-8000-000000000011');
insert into public.profiles(id,role,full_name,is_active) values('16500000-0000-4000-8000-000000000011','teacher','TEST-SESSIONS-GV',true);
insert into public.teachers(id,user_id) values('16500000-0000-4000-8000-000000000012','16500000-0000-4000-8000-000000000011');
insert into public.b2c_teachers(id,full_name,source_teacher_id) values('16500000-0000-4000-8000-000000000013','TEST-SESSIONS-GV','16500000-0000-4000-8000-000000000012');
update public.b2c_classes set teacher_name='TEST-SESSIONS-GV' where id='16500000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"16500000-0000-4000-8000-000000000011","role":"authenticated"}',true);
set local role authenticated;
select ok((public.read_teacher_b2c_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->>'session_summary') is null,'Teacher without attendance grant cannot read totals');
reset role;
insert into public.b2c_teacher_permissions(teacher_id,permissions,updated_by) values('16500000-0000-4000-8000-000000000013',array['view_classes','view_students','view_schedule','mark_attendance'],'16500000-0000-4000-8000-000000000010');
set local role authenticated;
select is(public.read_teacher_b2c_workspace('16500000-0000-4000-8000-000000000001','students')->'rows'->0->'session_summary'->>'attended','3','Granted teacher reads own class totals');
select throws_ok($$select public.read_b2c_class_workspace('16500000-0000-4000-8000-000000000001','students')$$,'42501',null,'Teacher cannot use manager endpoint');
select * from finish();
rollback;
